/**
 * Generates a keypair file in solana-keygen format, so you don't need the
 * Solana CLI installed to get started on devnet.
 *
 * DEVNET ONLY. For mainnet, install the CLI and run
 *   solana-keygen new -o ./deployer-mainnet.json
 * so the key is generated by you, on your machine, from your entropy.
 */
import { Keypair } from "@solana/web3.js";
import fs from "fs";

const out = process.argv[2] ?? "./deployer-devnet.json";
if (fs.existsSync(out)) {
  console.error(`${out} already exists. Refusing to overwrite a keypair.`);
  process.exit(1);
}

const kp = Keypair.generate();
fs.writeFileSync(out, JSON.stringify(Array.from(kp.secretKey)));
console.log(`${out}\n${kp.publicKey.toBase58()}`);
